const CHECKPOINT_KINDS = new Set([
  'production_validation_failure',
  'client_approval_needed',
  'production_approval_needed',
  'external_email_client_send_approval_needed',
]);
const MAX_MESSAGES_PER_MINUTE = 5;
const DEDUPE_TTL_MS = 24 * 60 * 60 * 1000;
const BURST_WINDOW_MS = 60 * 1000;

const root = $input.first().json || {};
const body = root.body && typeof root.body === 'object' ? root.body : root;
const now = Date.now();
let route = '';
let telegramText = '';
let stableEventId = '';

if (String(body.event_type || '').trim() === 'corpflow.lead_rescue.intake_received') {
  const payload = body.payload && typeof body.payload === 'object' ? body.payload : {};
  const prospect = payload.prospect && typeof payload.prospect === 'object' ? payload.prospect : {};
  const leadId = String(payload.lead_id || body.correlation_id || body.id || '').trim();
  const businessName = String(prospect.business_name || '').trim() || '(business name missing)';
  const contactName = String(prospect.contact_name || '').trim() || '(first name missing)';
  const adminUrl = String(payload.admin_detail_url || payload.admin_detail_path || '').trim();
  if (!leadId || !adminUrl) return [];
  route = 'lead_rescue';
  stableEventId = String(body.id || leadId).trim();
  telegramText = `Lead Rescue intake received\n\nBusiness: ${businessName}\nFirst name: ${contactName}\nLead ref: ${leadId}\nReview URL: ${adminUrl}\n\nAction required: Review within 2 business hours.`;
} else if (String(body.envelope || '').trim() === 'corpflow.ops_alert.v1') {
  const kind = String(body.kind || '').trim();
  const message = String(body.message || body.meta?.notification_text || '').trim();
  if (!CHECKPOINT_KINDS.has(kind) || !message) return [];
  route = 'ops_alert';
  stableEventId = String(
    body.id ||
    body.event_id ||
    body.idempotency_key ||
    `${body.envelope}:${kind}:${body.ticket_id || 'global'}:${body.at || ''}`
  ).trim();
  telegramText = message;
} else {
  return [];
}

if (!stableEventId || !telegramText.trim()) return [];

const state = $getWorkflowStaticData('global');
state.seen_event_ids = state.seen_event_ids || {};
state.message_times = Array.isArray(state.message_times) ? state.message_times : [];
for (const [eventId, seenAt] of Object.entries(state.seen_event_ids)) {
  if (!Number.isFinite(seenAt) || now - seenAt >= DEDUPE_TTL_MS) delete state.seen_event_ids[eventId];
}
state.message_times = state.message_times.filter(
  (sentAt) => Number.isFinite(sentAt) && now - sentAt < BURST_WINDOW_MS,
);
if (state.seen_event_ids[stableEventId]) return [];
if (state.message_times.length >= MAX_MESSAGES_PER_MINUTE) return [];

state.seen_event_ids[stableEventId] = now;
state.message_times.push(now);
return [{
  json: {
    route,
    event_id: stableEventId,
    telegram_text: telegramText.trim().slice(0, 3500),
  },
}];
